-- test-only tables that mirror the live columns and constraints the AI gate touches
create table public.locked (gym_id uuid primary key);
create or replace function private.gym_is_open(g uuid) returns boolean language sql stable as $$ select not exists (select 1 from public.locked where gym_id = g) $$;
create table public.members (id uuid primary key default gen_random_uuid(), gym_id uuid not null references public.gyms(id) on delete cascade, profile_id uuid, name text not null, phone text, gender text, goal text, plan_id uuid, start_date date, end_date date, status text not null default 'Active', joined_on date not null default current_date, notes text, wa_opt_out boolean not null default false);
create table public.leads (id uuid primary key default gen_random_uuid(), gym_id uuid not null references public.gyms(id) on delete cascade, name text not null, phone text, source text not null default 'Walk-in', stage text not null default 'New' check (stage in ('New','Contacted','Trial','Converted','Lost')), interest text, note text, follow_up_on date, converted_member_id uuid references public.members(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.invoices (id uuid primary key default gen_random_uuid(), gym_id uuid not null, no text, member_id uuid not null references public.members(id) on delete cascade, date date not null default current_date, due date, items jsonb not null default '[]', subtotal numeric not null default 0, discount numeric not null default 0, gst_pct numeric not null default 0, gst_amt numeric not null default 0, total numeric not null default 0, cancelled boolean not null default false);
create table public.payments (id uuid primary key default gen_random_uuid(), gym_id uuid not null, invoice_id uuid not null references public.invoices(id) on delete cascade, member_id uuid not null, amount numeric not null, method text not null default 'Cash', paid_on date not null default current_date);
create table public.emi_plans (id uuid primary key default gen_random_uuid(), invoice_id uuid not null, status text not null default 'active');
create table public.visits (id uuid primary key default gen_random_uuid(), member_id uuid not null references public.members(id) on delete cascade, in_at timestamptz not null default now());
create table public.gym_tasks (id uuid primary key default gen_random_uuid(), gym_id uuid not null references public.gyms(id) on delete cascade, title text not null check (char_length(btrim(title)) between 1 and 120), note text check (char_length(note) <= 500), priority text not null default 'Medium' check (priority in ('Low','Medium','High')), due_on date, assigned_to uuid, done_at timestamptz, created_by uuid, created_at timestamptz not null default now());
